mapper.select:
select dp.id, dp.order_id, dp.city_code, dp.expire_time, dp.create_time, o.schedule_date, o.time_slot, o.address, o.consignee, o.phone, o.amount from dispatch_pool dp join orders o on dp.order_id = o.id where dp.status = #{statusPending}
and dp.city_code = #{cityCode}
order by dp.create_time asc

select dp.id, dp.order_id, dp.city_code, dp.expire_time, dp.create_time, dp.status, dp.dispatch_type, dp.coach_id, dp.dispatch_time, o.schedule_date, o.time_slot, o.address, o.consignee, o.phone, o.amount, o.order_number from dispatch_pool dp join orders o on dp.order_id = o.id
and dp.status = #{status}
and dp.city_code = #{cityCode}
order by dp.create_time desc
